$db=new PDO('sqlite::memory:');$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$db->exec(file_get_contents(__DIR__.'/../api/life/schema.sql'));$store=new LifeStore($db);$store->initialize('test-only-owner-passphrase');new LifeAccounts($db);
$dir=LifeGoogleAuth::privateDir();if(!is_dir($dir))mkdir($dir,0700,true);file_put_contents($dir.'/config.php','<?php return '.var_export(['encryptionKey'=>base64_encode(str_repeat('x',32))],true).';');$checks=0;
function check(bool $ok,string $message):void{global $checks;if(!$ok)throw new RuntimeException($message);$checks++;}
$remote=[];$calls=[];$transport=function($method,$path,$body)use(&$remote,&$calls){$calls[]=[$method,$path,$body];if($method==='POST'&&$path==='tasks/v1/users/@me/lists')return ['id'=>'life-list'];if($method==='GET')return ['items'=>array_values($remote)];if($method==='POST'){$id='remote-'.count($remote);return $remote[$id]=['id'=>$id]+$body;}if($method==='PATCH'){$id=basename($path);return $remote[$id]=array_merge($remote[$id],$body);}if($method==='DELETE'){unset($remote[basename($path)]);return [];}throw new RuntimeException('Unexpected call');};
$sync=new LifeGoogleSync($store,$transport);$sync->connect(['refresh_token'=>'test-only','scope'=>'https://www.googleapis.com/auth/tasks']);$board=$store->read();$board=$store->mutate($board['version'],'task.save',['title'=>'Test tomorrow','notes'=>'Private description','dueDate'=>'2026-10-13','listId'=>$board['state']['lists'][0]['id']]);$id=$board['state']['tasks'][0]['id'];$sync->run();check(count($remote)===1,'Export exactly one task');$remoteId=array_key_first($remote);check($remote[$remoteId]['due']==='2026-10-13T00:00:00.000Z','Date mapping');$sync->run();check(count($remote)===1,'Repeated run does not duplicate');
$remote[$remoteId]['status']='completed';$sync->run();$s=$store->read()['state'];$done=array_column(array_filter($s['lists'],fn($l)=>$l['isDone']),'id');check(in_array($s['tasks'][0]['listId'],$done,true),'Google completion reaches Life');
$b=$store->read();$store->mutate($b['version'],'task.rename',['id'=>$id,'title'=>'Life change']);$remote[$remoteId]['title']='Google change';$sync->run();check(count($sync->status()['conflicts'])===1,'Conflicting edits retained');check($store->read()['state']['tasks'][0]['title']==='Life change','Local conflict preserved');$sync->resolve(['taskId'=>$id,'kind'=>'tasks','choice'=>'life']);$sync->run();check($remote[$remoteId]['title']==='Life change','Chosen Life version exported');check(!$sync->status()['conflicts'],'Conflict cleared');
$accounts=new LifeAccounts($db);$account=$accounts->signIn(['sub'=>'sync-other','email'=>'other@example.com','email_verified'=>true]);$other=new LifeGoogleSync(new LifeStore($db,(int)$account['id']),$transport);check(!$other->status()['connected']&&!$other->status()['conflicts'],'Connection and conflicts scoped');
$calendarOnly=new LifeGoogleSync(new LifeStore($db,(int)$account['id']),$transport);$calendarOnly->connect(['refresh_token'=>'calendar-token','scope'=>'https://www.googleapis.com/auth/calendar.app.created'],'calendar');check($calendarOnly->status()['calendarConnected']&&!$calendarOnly->status()['tasksConnected'],'Calendar consent is independent');$calendarOnly->connect(['scope'=>'https://www.googleapis.com/auth/tasks'],'tasks');check($calendarOnly->status()['calendarConnected']&&$calendarOnly->status()['tasksConnected'],'Separate consent connects both services');
$before=count($remote);$sync->disconnect();$sync->run();check(count($remote)===$before&&!$sync->status()['connected'],'Disconnect leaves Google records');$q=$db->prepare('SELECT token FROM life_google_connection WHERE id=1');$q->execute();check($q->fetchColumn()==='','Disconnect removes stored credentials');check(!$sync->status()['calendarConnected']&&!$sync->status()['tasksConnected'],'Disconnect clears service connection state');$sync->connect(['refresh_token'=>'reconnected','scope'=>'https://www.googleapis.com/auth/tasks'],'tasks');check($sync->status()['connected']&&$sync->status()['tasksConnected'],'Reconnect works after credentials were removed');
$payload=LifeGoogleAuth::encrypt(['refresh_token'=>'test'],1);check(LifeGoogleAuth::decrypt($payload,1)['refresh_token']==='test','Encrypted token round trip');try{LifeGoogleAuth::decrypt($payload,2);throw new RuntimeException('Cross account decryption should fail');}catch(LifeError $e){check(true,'Token encryption bound to account');}
check(!LifeGoogleSync::webhook($db,['channel'=>'unknown','token'=>'bad','resource'=>'none']),'Unrecognized webhook rejected');
